Response readRegisters(const Request& request, Exchange& exchange, uint32_t budget_ms) {
  Frame outgoing, incoming;
  if (!encodeRequest(request, outgoing) || budget_ms == 0) return error(Status::InvalidRequest);
  switch (exchange.transact(outgoing, budget_ms, incoming)) {
    case Io::Complete:
      return decodeResponse(request, incoming);
    case Io::Timeout:
      return error(Status::Timeout);
    case Io::Fault:
      return error(Status::TransportFault);
  }
  return error(Status::TransportFault);
}
